_chip1_process_all:
    call _bus_clear_all;    /* zero all bus accumulators */
/* SIMD PAIR ORDER (DSP4_PAIRED_GRAPH). Head A, head B,
 * the two paired dynamics calls, tail A, tail B --
 * 399 positions against 431 strip-ordered ones, because each
 * pair replaces four dynamics nodes with two driver
 * calls. DSP4_NODE_LIMIT COUNTS THESE POSITIONS in
 * this build, so limits 1..18 walk exactly one pair.
 */
#if DSP4_BQ_PAIRED_GRAPH
#if DSP4_CHAN_MASK && (DSP4_STRIPS == 0 || 0 < DSP4_STRIPS)
    /* strip 1+2: entries 0..10, gate group 0 */
    r2 = dm(_mask_on + 0);
    r2 = pass r2;
    if eq jump (pc, .bqgrunm0_end);
#endif
#if (DSP4_NODE_LIMIT == 0 || 0 < DSP4_NODE_LIMIT) && (DSP4_STRIPS == 0 || 0 < DSP4_STRIPS)
    call _C1_IN_01_process;
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = _buf_C1_IN_01;
    r1 = BLK_CHAIN_A_P1;
    call _scope_tap;
#endif
#endif
#if DSP4_BLOCK_KERNELS
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = _rx_slot_C1_IN_01;
    r1 = BLK_CHAIN_A_P1;
#endif
    call _scope_inject_blk;
#endif
#if (DSP4_NODE_LIMIT == 0 || 1 < DSP4_NODE_LIMIT) && (DSP4_STRIPS == 0 || 0 < DSP4_STRIPS)
    call _C1_GAIN_01_process;
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = _buf_C1_GAIN_01;
    r1 = BLK_CHAIN_B_P1;
    call _scope_tap;
#endif
#endif
#if DSP4_BLOCK_KERNELS
#if (DSP4_NODE_LIMIT == 0 || 1 < DSP4_NODE_LIMIT)
    call _C1_MTR_01_process;
#endif
#endif
#if (DSP4_NODE_LIMIT == 0 || 2 < DSP4_NODE_LIMIT) && (DSP4_STRIPS == 0 || 1 < DSP4_STRIPS)
    call _C1_IN_02_process;
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = _buf_C1_IN_02;
    r1 = BLK_CHAIN_A;
    call _scope_tap;
#endif
#endif
#if (DSP4_NODE_LIMIT == 0 || 3 < DSP4_NODE_LIMIT) && (DSP4_STRIPS == 0 || 1 < DSP4_STRIPS)
    call _C1_GAIN_02_process;
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = _buf_C1_GAIN_02;
    r1 = BLK_CHAIN_B;
    call _scope_tap;
#endif
#endif
#if DSP4_BLOCK_KERNELS
#if (DSP4_NODE_LIMIT == 0 || 3 < DSP4_NODE_LIMIT)
    call _C1_MTR_02_process;
#endif
#endif
#if (DSP4_NODE_LIMIT == 0 || 4 < DSP4_NODE_LIMIT) && (DSP4_STRIPS == 0 || 1 < DSP4_STRIPS)
    call _BQPFILT_01_02_process;
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = _buf_C1_FILT_01;
    r1 = BLK_CHAIN_B_P1;
    call _scope_tap;
#endif
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = _buf_C1_FILT_02;
    r1 = BLK_CHAIN_B;
    call _scope_tap;
#endif
#elif (DSP4_NODE_LIMIT == 0 || 4 < DSP4_NODE_LIMIT) && (DSP4_STRIPS == 0 || 0 < DSP4_STRIPS)
    call _C1_FILT_01_process;
#if DSP4_BLOCK_KERNELS && DSP4_SCOPE_BLK_TAP
    r0 = _buf_C1_FILT_01;
